    .and_then(|b| String::from_utf8(b).ok())
    .unwrap_or_else(|| "none".to_string());
Ok(vec![Effect::Echo(EchoPayload {
    level: EchoLevel::Info,
    text: format!("{}:{}", host_services::store_generation(), value),
