        // `sql`-on-`sequel` needs.
        grammar_name: Some("markdown".to_string()),
        extensions: exts.iter().map(|s| (*s).to_string()).collect(),
        grammar,
        highlights: Some(HIGHLIGHTS.to_string()),
        folds: None,
        injections: None,
        indents: None,
        textobjects: None,
        conceal_rules: vec![],
    }
}

// Distinct levels + contexts so the host test can assert routing, level
// mapping, and the context→category rendering. `info`/`warn` are kept at
// the default gate; `debug`/`trace` only when the plugin is raised.
logging::log(Level::Info, "boot", "logging guest activated");
logging::log(Level::Warn, "index", "reindex found 2 stale entries");
logging::log(Level::Debug, "detail", "walked 40 files in 3ms");
logging::log(Level::Error, "", "a context-less error line");

fn media_blocks(ctx: DecorationContext, _text: String) -> Result<Vec<MediaBlock>, String> {
    if ctx.line_count == 0 {
        // Graceful: nothing to scan → a typed guest err, not a trap.
        return Err("media-guest: empty buffer".to_string());
    }
    Ok(vec![
        MediaBlock {
            anchor_line: 1,
            // Relative — the host resolves it against the buffer's own
            // directory, which is what `[[file:diagram.png]]` means.
            path: "img/diagram.png".to_string(),
            alt: Some("a wiring diagram".to_string()),
            fit: MediaFit::Contain,
        },
        MediaBlock {
            anchor_line: ctx.line_count - 1,
            path: "/tmp/absolute.png".to_string(),
            // No alt — the host falls back to the file name.
            alt: None,
            fit: MediaFit::Width,
        },
    ])
}

if let Event::PluginLoaded(p) = ev {
    // Deferred config: enable auto-pair-mode the moment auto-pair loads.
    if p.name == "auto-pair" {
        modes::enable_mode("auto-pair-mode");
        // …and SET one of its options, which is the other half of the
        // documented deferred shape and the half that was never driven.
        // `enable-mode` reaches the bus; `set-option` reaches the config
        // registry, and the events store did not carry one — so this
        // call warned and no-oped while the test above still passed.
        // Full name, not the short one: `set-option` prefixes with the
        // CALLING plugin's id, so `style` would resolve as `init.style`.
        config::set_option("auto-pair.style", "manual");
